"""Dot, span, and path layers for the week 10 "Dot, Span, Path" slide.

Writes three transparent SVGs beside this script on one portrait golden-ratio canvas (618 x 1000) and one shared map scale, so they stack with `.r-stack` as fragments: each layer is a snapshot of the full route. Geometry and color come from the Blue Line map art (docs/assets/blue-line-full-path.svg, docs/assets/blue-line-map-stops/):

    dot.svg    Logan Square, one station dot
    span.svg   Logan Square and the next four stations down the Milwaukee diagonal, each drawn like the dot
    path.svg   the full Blue Line route, smooth, no station dots; stacked last, it covers the dot and span

    python3 docs/assets/dot-span-path/make_figures.py
"""
from pathlib import Path

HERE = Path(__file__).resolve().parent

PHI = (1 + 5**0.5) / 2
WIDTH = 618
HEIGHT = round(WIDTH * PHI)  # 1000
MARGIN = 40

BLUE = "#018bff"  # the map art's line color, not the official CTA #00a1de
LINE_W = 26  # route stroke in map units
STATION_R = 9.4  # white station dot in map units

# Full route from blue-line-full-path.svg, with the separately drawn top straight folded into one path.
ROUTE = "M36,60 L399.36,60 A40.5,40.5 0 0 1 433.99,79.5 L561.9,290.41 A45.5,45.5 0 0 1 568.5,314.01 L568.5,358.75 A66.5,66.5 0 0 0 573.71,384.56 L746.2,794.23 A22.5,22.5 0 0 0 766.94,808 L828.5,808 A21.5,21.5 0 0 1 850,829.5 L850,958 A21,21 0 0 1 829,979 L106,979"
ROUTE_BBOX = (36, 60 - LINE_W / 2, 850 + LINE_W / 2, 979 + LINE_W / 2)  # stroked extent

# Station centers from blue-line-full-path.svg, Logan Square first.
STATIONS = [(570.99, 377.7), (594.48, 434.33), (618.02, 490.98), (641.69, 547.54), (666.1, 604.13)]


def svg(body, title):
    x0, y0, x1, y1 = ROUTE_BBOX
    scale = (WIDTH - 2 * MARGIN) / (x1 - x0)
    tx = WIDTH / 2 - scale * (x0 + x1) / 2
    ty = HEIGHT / 2 - scale * (y0 + y1) / 2
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{WIDTH}" height="{HEIGHT}" viewBox="0 0 {WIDTH} {HEIGHT}" role="img">\n  <title>{title}</title>\n  <g transform="translate({tx:.2f} {ty:.2f}) scale({scale:.4f})">\n{body}\n  </g>\n</svg>\n'


def station(x, y):
    return f'    <circle cx="{x}" cy="{y}" r="{STATION_R}" fill="#fff"/>'


def ring(x, y):
    return f'    <circle cx="{x}" cy="{y}" r="{LINE_W / 2}" fill="{BLUE}"/>\n{station(x, y)}'


def dot():
    return svg(ring(*STATIONS[0]), "Dot: one Blue Line station")


def span():
    return svg("\n".join(ring(x, y) for x, y in STATIONS), "Span: a few Blue Line stations in a row")


def path():
    return svg(f'    <path d="{ROUTE}" fill="none" stroke="{BLUE}" stroke-width="{LINE_W}"/>', "Path: the full Blue Line route")


if __name__ == "__main__":
    for name, make in [("dot", dot), ("span", span), ("path", path)]:
        (HERE / f"{name}.svg").write_text(make())
